import { Headers, Request, Response, fetch, install } from './index.js';

const headers = new Headers({ 'X-Test': 'one' });
headers.append('x-test', 'two');
if (headers.get('X-TEST') !== 'one, two') throw new Error('Headers failed');
print('ok   fetch.Headers');

const req = new Request('https://example.com/a?b=1');
if (req.method !== 'GET' || req.url.indexOf('example.com') < 0) throw new Error('Request failed');
print('ok   fetch.Request');

const res = new Response('halo', { status: 201, statusText: 'Created' });
if (!res.ok || await res.text() !== 'halo') throw new Error('Response failed');
print('ok   fetch.Response');

let rejected = false;
try { await fetch('https://example.com', { method: 'POST' }); } catch (e) { rejected = true; }
if (!rejected) throw new Error('unsupported method should reject');
print('ok   fetch.unsupported-method');

const target = {};
install(target);
if (typeof target.fetch !== 'function' || typeof target.Response !== 'function') throw new Error('install failed');
print('ok   fetch.install');
print('ALL_OK');
